import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, time, id)
    sell_heap = []  # (price, time, id)
    book = {}  # id -> {'side','price','qty','time','active'}
    time_counter = 0

    for o in orders:
        typ = o[0]
        if typ == 'cancel':
            oid = o[1]
            if oid in book:
                book[oid]['active'] = False
            continue

        oid = o[1]
        side = o[2]
        if typ == 'market':
            price = None
            qty = o[3]
        else:
            price = o[3]
            qty = o[4]

        time_counter += 1
        cur_time = time_counter

        remaining = qty

        if side == 'buy':
            opp_heap = sell_heap
            while remaining > 0 and opp_heap:
                neg_or_price, t, rid = opp_heap[0]
                resting = book.get(rid)
                if resting is None or not resting['active'] or resting['qty'] <= 0:
                    heapq.heappop(opp_heap)
                    continue
                rprice = resting['price']
                if typ != 'market' and rprice > price:
                    break
                heapq.heappop(opp_heap)
                trade_qty = min(remaining, resting['qty'])
                trades.append([oid, rid, rprice, trade_qty])
                remaining -= trade_qty
                resting['qty'] -= trade_qty
                if resting['qty'] > 0:
                    heapq.heappush(opp_heap, (rprice, t, rid))
                else:
                    resting['active'] = False
        else:
            opp_heap = buy_heap
            while remaining > 0 and opp_heap:
                negprice, t, rid = opp_heap[0]
                resting = book.get(rid)
                if resting is None or not resting['active'] or resting['qty'] <= 0:
                    heapq.heappop(opp_heap)
                    continue
                rprice = resting['price']
                if typ != 'market' and rprice < price:
                    break
                heapq.heappop(opp_heap)
                trade_qty = min(remaining, resting['qty'])
                trades.append([rid, oid, rprice, trade_qty])
                remaining -= trade_qty
                resting['qty'] -= trade_qty
                if resting['qty'] > 0:
                    heapq.heappush(opp_heap, (negprice, t, rid))
                else:
                    resting['active'] = False

        if typ == 'limit' and remaining > 0:
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'time': cur_time, 'active': True}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, cur_time, oid))
            else:
                heapq.heappush(sell_heap, (price, cur_time, oid))
        elif typ == 'limit' and remaining == 0:
            book[oid] = {'side': side, 'price': price, 'qty': 0, 'time': cur_time, 'active': False}

    return trades

